require __DIR__.'/common.php';devize_ready($pdo);$id=max(0,(int)($_GET['id']??$_POST['id']??0));$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 deviz_check();$names=$_POST['name']??[];$qty=$_POST['quantity']??[];$prices=$_POST['price']??[];$items=[];
 if(!is_array($names)||!is_array($qty)||!is_array($prices))$error='Date invalide.';
 else foreach($names as $k=>$name){$name=trim((string)$name);$q=str_replace(',','.',(string)($qty[$k]??''));$p=str_replace(',','.',(string)($prices[$k]??''));if($name===''&&$q===''&&$p==='')continue;if($name===''||!is_numeric($q)||!is_numeric($p)||(float)$q<=0||(float)$p<0||strlen($name)>500){$error='Completează corect fiecare poziție (denumire, cantitate și preț).';break;}$items[]=[$name,(float)$q,(float)$p];}
 if(!$items&&!$error)$error='Adaugă cel puțin o poziție.';
 if(count($items)>500)$error='Maximum 500 poziții per deviz.';
 if(!$error){try{$pdo->beginTransaction();$title=mb_substr(trim((string)($_POST['title']??'')),0,200);$notes=mb_substr(trim((string)($_POST['notes']??'')),0,5000);$vatRaw=trim((string)($_POST['vat_rate']??''));$vat=$vatRaw===''?null:(float)str_replace(',','.',$vatRaw);if($vat!==null&&(!is_numeric(str_replace(',','.',$vatRaw))||$vat<0||$vat>100))throw new Exception('TVA trebuie să fie între 0 și 100%.');
 if($id){$s=$pdo->prepare('UPDATE eco_devize SET title=?,notes=?,vat_rate=? WHERE id=?');$s->execute([$title,$notes,$vat,$id]);if(!$s->rowCount()){ $s=$pdo->prepare('SELECT id FROM eco_devize WHERE id=?');$s->execute([$id]);if(!$s->fetch())throw new Exception('Deviz inexistent.');}$pdo->prepare('DELETE FROM eco_devize_items WHERE deviz_id=?')->execute([$id]);}
 else{$pdo->prepare('INSERT INTO eco_devize (title,notes,vat_rate) VALUES (?,?,?)')->execute([$title,$notes,$vat]);$id=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE eco_devize SET number=? WHERE id=?')->execute(['ECO_DEVIZ'.str_pad((string)$id,2,'0',STR_PAD_LEFT),$id]);}
 $s=$pdo->prepare('INSERT INTO eco_devize_items (deviz_id,sort_order,name,quantity,unit_price) VALUES (?,?,?,?,?)');foreach($items as $i=>$item)$s->execute([$id,$i+1,$item[0],$item[1],$item[2]]);$pdo->commit();header('Location: /devize/edit.php?id='.$id.'&saved=1');exit;
 }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error='Nu s-a putut salva devizul: '.$ex->getMessage();}}
}
$deviz=null;$items=[];if($id){$s=$pdo->prepare('SELECT * FROM eco_devize WHERE id=?');$s->execute([$id]);$deviz=$s->fetch();if(!$deviz){http_response_code(404);exit('Deviz inexistent.');}$items=deviz_items($pdo,$id);}if($_SERVER['REQUEST_METHOD']==='POST'){$items=[];foreach(($_POST['name']??[]) as $k=>$v)$items[]=['name'=>$v,'quantity'=>$_POST['quantity'][$k]??1,'unit_price'=>$_POST['price'][$k]??0];}
