<style>.dv-edit{max-width:1050px;margin:auto;color:#172033}.dv-edit .head{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:20px}.dv-edit h1{font-size:27px;margin:0}.dv-edit .panel{background:#fff;border:1px solid #e5ebf1;border-radius:15px;padding:22px;margin-bottom:16px}.dv-edit label{display:block;font-size:12px;font-weight:700;margin-bottom:7px}.dv-edit input,.dv-edit textarea{width:100%;border:1px solid #d9e2ec;border-radius:9px;padding:12px;font:inherit;min-width:0;background:white}.dv-edit input:focus,.dv-edit textarea:focus{outline:2px solid #b8d9f4}.dv-edit .line{display:grid;grid-template-columns:44px minmax(180px,1fr) 105px 145px 150px 34px;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid #eef1f5}.dv-edit .line.header{font-size:11px;font-weight:700;color:#65748a}.dv-edit .line .sum{text-align:right;font-weight:700}.dv-edit .remove{background:#fff0ed;color:#bd352d;border:0;border-radius:8px;padding:10px;cursor:pointer}.dv-edit .btn{display:inline-block;border:0;border-radius:10px;padding:12px 18px;font:inherit;font-weight:700;cursor:pointer;text-decoration:none;background:#edf3f9;color:#1769aa}.dv-edit .primary{background:#1769aa;color:#fff}.dv-edit .total{text-align:right;font-size:20px;font-weight:800;margin:20px 0}.dv-edit .actions{display:flex;gap:10px;flex-wrap:wrap}.dv-edit .notice{padding:12px;border-radius:10px;background:#eaf8ee;color:#21643d;margin-bottom:15px}.dv-edit .error{background:#fff0ee;color:#ad3029}@media(max-width:780px){.dv-edit .panel{padding:14px}.dv-edit .line.header{display:none}.dv-edit .line{grid-template-columns:1fr 1fr;gap:8px;background:#f8fafc;border:1px solid #e8edf2;border-radius:12px;padding:12px;margin:12px 0}.dv-edit .line .idx{grid-column:1/-1;font-weight:700}.dv-edit .line .name{grid-column:1/-1}.dv-edit .line .sum{align-self:center}.dv-edit .actions .btn{flex:1;text-align:center}.dv-edit .head{align-items:stretch}} .dv-edit .dv-tip{font-size:12px;color:#5c718b;line-height:1.65;margin:10px 0 0}.dv-vat-preview{margin-top:12px;background:#eef6ff;color:#1359a0;padding:13px;border-radius:12px;font-weight:700}.dv-edit .panel{box-shadow:0 6px 30px rgba(24,74,135,.035)}.dv-edit .primary{background:linear-gradient(120deg,#1465b4,#278be1)} </style>
<div class="dv-edit"><div class="head"><div><h1><?=e($deviz['number']??'Deviz nou')?></h1><small>Prețuri în EUR, fără TVA</small></div><a href="/devize/" class="btn">← Toate devizele</a></div><?php if(isset($_GET['saved'])):?><div class="notice">Devizul a fost salvat.</div><?php endif;?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><form method="post" id="devizForm"><input type="hidden" name="csrf" value="<?=deviz_token()?>"><input type="hidden" name="id" value="<?=$id?>"><div class="panel"><label for="title">Titlu / descriere (opțional)</label><input id="title" name="title" maxlength="200" placeholder="Ex.: Lucrări și materiale" value="<?=e($_POST['title']??$deviz['title']??'')?>"></div><div class="panel"><h3 style="margin:0 0 12px">Produse / lucrări</h3><div class="line header"><span>NR. CRT.</span><span>Denumire produs / lucrare</span><span>Buc.</span><span>Preț / buc. fără TVA</span><span>Total EUR fără TVA</span><span></span></div><div id="rows"></div><button class="btn" type="button" id="add">+ Adaugă poziție</button><div class="total">Total fără TVA: <span id="grand">0,00</span> EUR</div></div><div class="panel"><label for="vat_rate">TVA (%) — opțional</label><input id="vat_rate" name="vat_rate" type="number" min="0" max="100" step="0.01" inputmode="decimal" placeholder="Lasă gol dacă nu aplici TVA" value="<?=e($_POST['vat_rate']??$deviz['vat_rate']??'')?>"><p class="dv-tip">Dacă lași TVA necompletat, devizul PDF va afișa numai prețurile fără TVA. Dacă introduci un procent, calculăm automat TVA și afișăm separat totalul fără TVA, TVA-ul și totalul cu TVA.</p><div id="vatPreview" class="dv-vat-preview" hidden></div></div><div class="panel"><label for="notes">Observații (opțional)</label><textarea id="notes" name="notes" rows="3" placeholder="Detalii suplimentare"><?=e($_POST['notes']??$deviz['notes']??'')?></textarea></div><div class="actions"><button class="btn primary" type="submit">Salvează devizul</button><?php if($id):?><a class="btn" href="/devize/pdf.php?id=<?=$id?>" target="_blank" rel="noopener">Export PDF</a><?php endif;?></div></form></div>
<script>
(()=>{const root=document.getElementById('rows'),fmt=n=>n.toLocaleString('ro-RO',{minimumFractionDigits:2,maximumFractionDigits:2}),num=v=>Number(String(v).replace(',','.'))||0;function recalc(){let total=0;[...root.children].forEach((r,i)=>{r.querySelector('.idx').textContent=i+1;let val=num(r.querySelector('.qty').value)*num(r.querySelector('.price').value);total+=val;r.querySelector('.sum').textContent=fmt(val)+' EUR'});document.getElementById('grand').textContent=fmt(total);const vat=document.getElementById('vat_rate'),preview=document.getElementById('vatPreview');if(vat&&preview){const rate=vat.value.trim();preview.hidden=rate==='';if(rate!==''){const amount=total*num(rate)/100;preview.textContent='TVA '+rate+'%: '+fmt(amount)+' EUR · Total cu TVA: '+fmt(total+amount)+' EUR'}}}function add(name='',qty='1',price='0'){const r=document.createElement('div');r.className='line';r.innerHTML='<span class="idx"></span><input class="name" name="name[]" required maxlength="500" placeholder="Denumire produs / lucrare"><input class="qty" name="quantity[]" type="number" min="0.001" step="0.001" required inputmode="decimal" aria-label="Număr bucăți"><input class="price" name="price[]" type="number" min="0" step="0.01" required inputmode="decimal" aria-label="Preț pe bucată EUR"><span class="sum"></span><button class="remove" type="button" aria-label="Elimină poziția">×</button>';r.querySelector('.name').value=name;r.querySelector('.qty').value=qty;r.querySelector('.price').value=price;r.querySelector('.remove').onclick=()=>{r.remove();recalc()};r.addEventListener('input',recalc);root.appendChild(r);recalc()}const initial=<?=json_encode(array_map(fn($i)=>[(string)$i['name'],(string)$i['quantity'],(string)$i['unit_price']],$items),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;initial.length?initial.forEach(x=>add(...x)):add();document.getElementById('add').onclick=()=>add();document.getElementById('vat_rate').addEventListener('input',recalc);recalc();document.getElementById('devizForm').onsubmit=()=>{if(!root.children.length){alert('Adaugă cel puțin o poziție.');return false}return true};})();
</script>
